mapper.select:
SELECT id,operation_id source_operation_id,space_id,workspace_id,file_operation_id,relative_path path,reserved_bytes max_bytes,
  reserved_version_id version_id,asset_id,object_key FROM pf.tool_output_capture
WHERE space_id=#{command.operation.spaceId} AND workspace_id=#{command.operation.workspaceId} AND file_operation_id=#{command.operation.id}

SELECT actual_bytes bytes,content_sha256 sha256 FROM pf.tool_output_capture
WHERE file_operation_id=#{command.operation.id} AND space_id=#{command.operation.spaceId} AND workspace_id=#{command.operation.workspaceId}
  AND actual_bytes IS NOT NULL AND content_sha256 IS NOT NULL

mapper.update:
UPDATE pf.tool_output_capture SET helper_stop_text=#{text},helper_stop_hash=#{hash},revision=revision+1
WHERE file_operation_id=#{command.operation.id} AND space_id=#{command.operation.spaceId} AND workspace_id=#{command.operation.workspaceId}
  AND (helper_stop_hash IS NULL OR helper_stop_hash=#{hash})

UPDATE pf.tool_output_capture SET status='COMMITTED',file_id=#{row.fileId},version_id=#{row.versionId},revision=revision+1
    WHERE file_operation_id=#{row.operationId} AND space_id=#{row.spaceId} AND workspace_id=#{row.workspaceId} AND status IN('CAPTURING','RECONCILING')
      AND actual_bytes=#{row.bytes} AND content_sha256=#{row.sha256}
